-- vyora-ai — publication de l'artefact (32633 caractères, 8 tranches).
-- Généré par scripts/build-edge-loader.mjs : ne pas éditer.
delete from public._edge_function_artifact_slices where name = 'vyora-ai';

insert into public._edge_function_artifact_slices(name, part, chunk)
values
  ('vyora-ai', 0, ''),
  ('vyora-ai', 1, ''),
  ('vyora-ai', 2, ''),
  ('vyora-ai', 3, ''),
  ('vyora-ai', 4, ''),
  ('vyora-ai', 5, ''),
  ('vyora-ai', 6, ''),
  ('vyora-ai', 7, '');

-- Le chargeur déployé recompose exactement ces tranches : on vérifie ici ce
-- qu'il lira, et non une constante recopiée à la main.
do $artifact$
declare
  assembled text;
  parts integer;
begin
  select count(*), string_agg(chunk, '' order by part)
    into parts, assembled
  from public._edge_function_artifact_slices where name = 'vyora-ai';

  if assembled is null or parts <> 8 then
    raise exception 'artefact % : % tranches publiées au lieu de %',
      'vyora-ai', coalesce(parts, 0), 8;
  end if;
  if exists (
    select 1 from public._edge_function_artifact_slices
    where name = 'vyora-ai'
      and (part < 0 or part >= 8
           or length(chunk) = 0 or length(chunk) > 2000)
  ) then
    raise exception 'artefact % : numérotation ou taille de tranche invalide', 'vyora-ai';
  end if;
  if length(assembled) <> 14964 then
    raise exception 'artefact % : % caractères base64 au lieu de %',
      'vyora-ai', length(assembled), 14964;
  end if;
  if md5(assembled) <> '0753ede2fe556b2e8909a96232a75c6f' then
    raise exception 'artefact % : empreinte des tranches différente du chargeur', 'vyora-ai';
  end if;
  raise notice 'artefact % publié : % caractères, % tranches, sha256 %',
    'vyora-ai', 32633, 8, '0c7e8aed286bc7772f906ee3aca1b690992e9ea9017ac022ed7efbf0f3656dc1';
end
$artifact$;
